.review
   &__main
      @extend .white-box
      @include margin-bottom(var(--gap))
      overflow: visible
   &__header
      display: flex
      gap: var(--gap-large)
      padding-bottom: var(--gap)
      border-bottom: 1px solid var(--gray-200)
   &__info
      @include margin-bottom(var(--gap-2))
   &__box
      flex-basis: 435px
      flex-shrink: 0
   &__content
      padding: var(--gap-2)
      display: flex
      flex-direction: column
      align-items: center
      gap: var(--gap-2)
      border-radius: 10px
      background: var(--gray-50)
   &__text
      text-align: center
      a
         color: var(--bronze)
         text-decoration: underline
   @media (max-width: 1660px)
      &__header
         gap: var(--gap)
   @include ms
      &__header
         flex-direction: column
      &__box
         flex-basis: auto
   @include xs
      &__content
         --gap-2: 15px