.bonus
   &__main
      @extend .two-col
   &__info
      @include margin-bottom(var(--gap-2))
   &__title
      @extend .title
   &__text
      @extend .fs-20
      @include margin-bottom(var(--gap-2))
   &__content
      @extend .gray-box
      padding: 25px
      & > *
         &:not(:last-child)
            border-bottom: 1px solid var(--gray-300)
      &-header
         padding-bottom: 15px
         display: flex
         align-items: center
         justify-content: space-between
         flex-wrap: wrap
         gap: var(--gap-3)
      &-labels
         display: flex
         flex-wrap: wrap
         gap: var(--gap-2)
      &-label
         @extend .title
         @extend .title--second
         padding: 9px 15px
         display: flex
         align-items: center
         gap: 15px
         border-radius: var(--border-radius)
         border: 1px solid var(--accent)
         background: #fff
      &-list
         @include ol
         & > *
            border-bottom: 1px solid var(--gray-300)
      &-item
         padding: 15px 0
         padding-left: 94px
         display: flex
         align-items: flex-start
         gap: var(--gap-2)
         &::before
            @extend .title
            @extend .title--second
            @extend .title--red
            width: 50px
            left: 0
      &-info
         @include margin-bottom(5px)
      &-name
         @extend .title
         @extend .title--second
         white-space: pre-line
      .badge
         margin-left: auto
   @include xl
      &__content
         &-item
            padding-left: 60px
   @include md
      &__main
         flex-direction: column
         gap: 30px
      &__content
         padding: 20px
         &-item
            padding-left: 50px
   @include ms
      &__content
         &-labels
            gap: 30px
         &-label
            padding: 7px 10px
   @include sm
      &__content
         padding: 15px
         &-header
            flex-direction: column
            align-items: flex-start
         &-item
            padding-left: 42px
            gap: var(--gap-3)
            &::before
               width: 32px
         &-label
            padding: 3px 5px